const FINALIZE_STARTERS = [
    {
        name: "Illustration polish",
        stages: [
            finalizeStage({
                kind: "refine"
            }),
            finalizeStage({
                kind: "upscale"
            }),
            finalizeStage({
                kind: "detail",
                enabled: false,
                creativity: .22
            })
        ]
    },
    {
        name: "Expression finishing",
        stages: [
            finalizeStage({
                kind: "refine",
                reference: true
            }),
            finalizeStage({
                kind: "upscale"
            }),
            finalizeStage({
                kind: "cutout"
            }),
            finalizeStage({
                kind: "despill"
            })
        ]
    },
    {
        name: "Environment polish",
        stages: [
            finalizeStage({
                kind: "refine"
            }),
            finalizeStage({
                kind: "upscale"
            })
        ]
    },
    {
        name: "Surgical correction",
        stages: [
            finalizeStage({
                kind: "detail",
                creativity: .22
            })
        ]
    }
];
const FINALIZE_ICONS = {
    refine: "wand",
    upscale: "upscale",
    detail: "rectangle",
    cutout: "background",
    despill: "despill"
};
function finalizeEscape(value) {
    return String(value ?? "").replace(/[&<>"']/g, (c)=>({
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
        })[c]);
}
function finalizeImageUrl(image) {
    return image.id ? `/api/v1/images/${encodeURIComponent(image.id)}` : "";
}
function finalizeConfig(details) {
    const parameters = {};
    for (const key of [
        "sampler",
        "scheduler",
        "vae",
        "qwenModel",
        "clipLModel",
        "clipGModel",
        "t5XXLModel"
    ])if (details?.parameters?.[key]) parameters[key] = details.parameters[key];
    if (details?.loras?.length) {
        parameters.loras = details.loras.map((v)=>v.name);
        parameters.loraWeights = details.loras.map((v)=>v.weight);
    }
    return {
        model: details?.model || "",
        prompt: details?.resolvedPrompt || details?.prompt || "",
        negativePrompt: details?.resolvedNegativePrompt || details?.negativePrompt || "",
        parameters
    };
}
async function finalizeDespillPixels(image, stage, signal) {
    const response = await fetch(finalizeImageUrl(image), {
        credentials: "same-origin",
        redirect: "error",
        signal
    });
    if (!response.ok) throw new Error("Could not read the source for despill.");
    const blob = await response.blob();
    if (blob.size > 50 * 1024 * 1024) throw new Error("Source exceeds the local editor limit.");
    const url = URL.createObjectURL(blob), bitmap = new Image();
    bitmap.src = url;
    try {
        await bitmap.decode();
        signal.throwIfAborted();
        const w = bitmap.naturalWidth, h = bitmap.naturalHeight;
        if (!w || !h || w * h > EDIT_MAX_PIXELS || Math.max(w, h) > EDIT_MAX_SIDE) throw new Error("Despill supports up to 16MP / 8192px.");
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(bitmap, 0, 0);
        const data = ctx.getImageData(0, 0, w, h);
        editDespill(data.data, w, h, new Uint8Array(w * h), stage.channel, stage.strength);
        ctx.putImageData(data, 0, 0);
        const png = canvas.toDataURL("image/png");
        canvas.width = canvas.height = 1;
        if (png.length > EDIT_DATA_LIMIT) throw new Error("Despill result exceeds the current PNG upload limit.");
        return png;
    } finally{
        URL.revokeObjectURL(url);
    }
}
async function combineAnimaReferences(refs) {
    if (refs.length !== 2) throw new Error("Choose exactly two saved references.");
    const bitmaps = [];
    try {
        for (const ref of refs){
            const response = await fetch(`/api/v1/images/${encodeURIComponent(ref.id)}`, {
                credentials: "same-origin",
                redirect: "error"
            });
            if (!response.ok) throw new Error("Could not read the selected reference.");
            const blob = await response.blob();
            if (blob.size > 50 * 1024 * 1024) throw new Error("Reference exceeds the local image limit.");
            bitmaps.push(await createImageBitmap(blob));
        }
        const canvas = document.createElement("canvas"), height = Math.max(1, Math.round(Math.min(768, Math.max(...bitmaps.map((b)=>Math.min(b.height, 768 * b.height / b.width))))));
        const widths = bitmaps.map((b)=>Math.max(1, Math.round(b.width * Math.min(height / b.height, 768 / b.width))));
        canvas.width = widths.reduce((a, b)=>a + b, 0);
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#808080";
        ctx.fillRect(0, 0, canvas.width, height);
        let x = 0;
        bitmaps.forEach((b, i)=>{
            const h = b.height * widths[i] / b.width;
            ctx.drawImage(b, x, (height - h) / 2, widths[i], h);
            x += widths[i];
        });
        return canvas.toDataURL("image/jpeg", .92);
    } finally{
        bitmaps.forEach((b)=>b.close());
    }
}
