            showModal("registry", "Character library", `${registryRows().length} identities · Shared artwork, independent cast direction`, `<div class="cast-registry-toolbar"><label class="field">Destination cast<select id="ss-cast-registry-destination" ${!state.casts.length ? "disabled" : ""}>${state.casts.map((c)=>`<option value="${E(c.id)}" ${c.id === registryDestination ? "selected" : ""}>${E(c.name)}</option>`).join("")}</select></label><label class="field">Search characters<input id="ss-cast-registry-search" type="search" value="${E(registryQuery)}" placeholder="Name, outfit or cast"></label></div><p class="hint">Link to share future artwork and wardrobe edits. Fork for independent edits. Copy an outfit when two versions already have different expression packs. Removing a member keeps its identity in the library.</p><div class="cast-registry-grid" data-registry-list></div>`, `<p data-registry-count>0 selected</p><div class="actions">${button("Close", "close-dialog", "ghost")}${button("Link selected", "registry-batch", "primary", "people", 'disabled')}</div>`, true);
