                const member = draft ? memberDraft : currentMember();
                member.referenceImageId = image.id;
                member.reference = `/api/v1/images/${encodeURIComponent(image.id)}`;
                if (!draft && member.wardrobes) {
                    const rows = castWardrobes(member);
                    rows[0].referenceImageId = image.id;
                    member.wardrobes = rows;
                }
