        surface.dataset.state = job.status;
        this.get('[data-role="background-label"]').textContent = label;
        const caption = this.get('[data-role="background-detail"]');
        caption.textContent = detail;
        caption.title = detail;
        const image = this.get('[data-role="background-preview"]');
        const source = job.imageId ? `/api/v1/images/${encodeURIComponent(job.imageId)}` : job.preview;
        image.hidden = !source;
        if (source && image.getAttribute("src") !== source) image.src = source;
        else if (!source) image.removeAttribute("src");
        image.onerror = ()=>{
            image.hidden = true;
            surface.dataset.hasPreview = "false";
        };
        surface.dataset.hasPreview = String(!image.hidden);
        const bar = this.get('[data-role="background-progress"]');
        bar.hidden = ![
            "queued",
            "generating"
        ].includes(job.status);
        if (progress === null) bar.removeAttribute("value");
        else bar.value = progress;
