            if (!this.cardLoaded || this.cardSave || !host.isConnected || this.cardIdentity(host, String(this.ctx.dom.getMessageId?.(host) || ""), this.currentCardSwipe(String(this.ctx.dom.getMessageId?.(host) || ""))) !== key) {
                message = "The source card changed. Reopen its editor.";
                sync();
                return;
            }
            const scope = tool === "expression" ? "card" : "member", requestId = createRequestId(), chatId = this.chatId;
