        this.get("persona-title").textContent = preset?.name || "New persona identity";
        const count = this.data.personaPresets.length;
        this.get("persona-profile-count").textContent = `${count} saved ${count === 1 ? "profile" : "profiles"}`;
        this.get("persona-profile-cards").closest(".ss-persona-directory").querySelector('[data-action="delete-persona-visual"]').disabled = !preset;
