        this.field("host-look-triggers").value = look?.triggerWords?.join(", ") || "";
        this.field("host-look-reference").value = look?.referenceImageUrl || "";
        this.field("host-look-thumbnail").value = look?.thumbnailUrl || "";
        this.field("host-look-notes").value = look?.notes || "";
