            id: existing?.id || "",
            name,
            aliases: list(this.field("host-look-aliases")?.value || ""),
            outfitPrompt: this.field("host-look-outfit")?.value || "",
            negativePrompt: this.field("host-look-negative")?.value || "",
            checkpoint: this.field("host-look-checkpoint")?.value || "",
            stackPresetId: this.field("host-look-stack")?.value || "",
            stackSnapshot: existing?.stackSnapshot || [],
            referenceImageId: existing?.referenceImageId || "",
            referenceImageUrl: this.field("host-look-reference")?.value.trim() || "",
            thumbnailImageId: existing?.thumbnailImageId || "",
            thumbnailUrl: this.field("host-look-thumbnail")?.value.trim() || "",
            triggerWords: list(this.field("host-look-triggers")?.value || ""),
