                    image.decode(),
                    new Promise((_, reject)=>{
                        if (controller.signal.aborted) reject(new Error("Aborted"));
                        else controller.signal.addEventListener("abort", ()=>reject(new Error("Aborted")), {
                            once: true
                        });
                    })
