const THEATER_LIVE_COMMANDS = {
    regenerate: 'action-regenerate',
    stop: 'action-stop-generation',
    left: 'action-swipe-left',
    right: 'action-swipe-right'
};
function theaterLiveNormalize(value) {
    return castPacketInput(value).normalize('NFKC').replace(/[\u200b-\u200d\ufeff]/g, '').replace(/\s+/gu, '').replace(/[*_`~]/g, '');
}
function theaterLiveSourceText(raw) {
    const cue = theaterCueParse(raw.trim());
    if (cue) return theaterLiveNormalize(theaterCueText(cue));
    if (/^\s*<swarm-background=[\s\S]*<\/swarm-background\s*>\s*$/i.test(raw)) return '';
    let text = castPacketInput(raw).replace(/<!--[\s\S]*?-->/g, '').replace(/<(think|thinking|reasoning|style|script)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '');
    text = text.replace(/!\[([^\]]*)\]\([^\n]*?\)/g, '$1').replace(/\[([^\]]*)\]\([^\n]*?\)/g, '$1').replace(/^\s{0,3}(?:#{1,6}\s+|>\s?)/gm, '');
    text = text.replace(/<img\b[^>]*>/gi, (tag)=>tag.match(/\balt\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i)?.slice(1).find((x)=>x !== undefined) || '');
    text = text.replace(/<\/?[a-z][a-z\d:_-]*(?=[\s=/>])(?:"[^"]*"|'[^']*'|[^'">])*>/gi, '');
    const decoder = document.createElement('textarea');
    decoder.innerHTML = text.replace(/</g, '&lt;');
    return theaterLiveNormalize(decoder.value);
}
function theaterLiveFrameText(frame) {
    if (frame.cueOnly) return theaterLiveNormalize(theaterCueText(frame.cueOnly));
    if (frame.kind === 'cast' || frame.kind === 'cg') return theaterLiveNormalize(frame.text);
    const copy = frame.content.cloneNode(true);
    for (const node of copy.querySelectorAll('style,script,svg'))node.remove();
    return theaterLiveNormalize(copy.textContent || '');
}
function theaterLiveVerified(frames, source) {
    const units = theaterLiveUnits(source).map(theaterLiveSourceText).filter(Boolean);
    let at = 0, accepted = 0;
    for (const unit of units){
        let text = '', cursor = at;
        while(cursor < frames.length && text.length < unit.length){
            const value = theaterLiveFrameText(frames[cursor]);
            if (!value || !unit.startsWith(text + value)) break;
            text += value;
            cursor++;
        }
        if (text !== unit) break;
        accepted = cursor;
        at = cursor;
    }
    return frames.slice(0, accepted);
}
function theaterLiveAppend(buffer, token, offset) {
    if (typeof offset !== 'number' || !Number.isSafeInteger(offset) || offset < 0) return {
        value: buffer,
        gap: true
    };
    if (offset > buffer.length) return {
        value: buffer,
        gap: true
    };
    const overlap = Math.min(token.length, buffer.length - offset);
    if (buffer.slice(offset, offset + overlap) !== token.slice(0, overlap)) return {
        value: buffer,
        gap: true
    };
    if (buffer.length + token.length - overlap > 1_000_000) return {
        value: buffer,
        gap: true
    };
    return {
        value: buffer + token.slice(overlap),
        gap: false
    };
}
function theaterFrameStamp(f) {
    if (!f) return '';
    const children = [
        ...f.content.childNodes
    ].map((n)=>n instanceof Element ? n.outerHTML : n.textContent || '').join('');
    return [
        f.key,
        f.scene,
        f.sceneKey,
        f.explicitMood,
        f.inheritedScene,
        f.inheritedMood,
        f.mood,
        f.moodDirected,
        f.sceneDirected,
        f.storySceneName,
        children,
        JSON.stringify(f.htmlContext || {}),
        JSON.stringify(f.fx || {}),
        JSON.stringify(f.cueOnly || {})
    ].join('\u0001');
}
function theaterRowStamp(frames) {
    return frames.map(theaterFrameStamp).join('\u0002');
}
function theaterLiveRecent(ctx) {
    try {
        const rows = ctx.messages?.getRecent?.(100);
        return Array.isArray(rows) ? rows.filter((m)=>m && typeof m.id === 'string') : [];
    } catch  {
        return [];
    }
}
function theaterLiveComposer(ctx, chat) {
    try {
        const c = ctx.composer;
        if (typeof c?.send !== 'function' || typeof c?.setText !== 'function') return null;
        const state = c.getState();
        return state?.mounted && state.chatId === chat ? state : null;
    } catch  {
        return null;
    }
}
function theaterLiveCommands(ctx) {
    try {
        return new Set((ctx.host?.surfaces?.list?.([
            'command'
        ]) || []).filter((x)=>x.invocable !== false).map((x)=>String(x.id)));
    } catch  {
        return new Set();
    }
}
