        shell.querySelector('.tools').append(theaterButton('backlog', 'Story backlog', THEATER_ICONS.backlog), theaterButton('gallery', 'CG gallery', THEATER_ICONS.gallery), theaterButton('settings', 'Theater settings', THEATER_ICONS.settings), theaterButton('hide', 'Hide controls', THEATER_ICONS.hide));
        const restore = theaterButton('hide', 'Show controls', THEATER_ICONS.hide, 'icon restore');
        restore.removeAttribute('title');
        shell.append(restore);
        const panelHead = shell.querySelector('.panel-head');
        const backToSettings = theaterButton('art-back', 'Back to playback settings', THEATER_ICONS.back, 'icon panel-back');
