        theaterArtPaint(shell, art);
        shell.dataset.frame = 'editorial';
        shell.dataset.island = 'bare';
        const f = this.frames.find((x)=>x.kind === kind && (kind !== 'cast' || x.content.querySelector('[data-swarm-cast]'))) || this.frames.find((x)=>x.kind === kind);
        const scene = document.createElement('div');
