            const projected = this.artProjection(preview, art);
            if (projected.firstElementChild instanceof HTMLElement) projected.firstElementChild.dataset.stagePattern = shell.dataset.stagePattern;
            const native = theaterNativeCast(preview, art, projected.firstElementChild);
