        if (this.panel === 'art' && !this.artDraft) {
            this.artDraft = theaterCleanArt(this.art);
            this.artError = '';
            this.artTab = 'looks';
            this.artCardQuery = '';
            this.artCardPage = 0;
        }
        ;
        if (this.panel === 'art' && tab) {
            this.artTab = tab;
            if (stage) this.artStageTab = stage;
        }
        if (this.panel) this.pause();
        this.renderPanel();
